class Solution:
    def minimumDifference(self, nums: List[int]) -> int:
        m = len(nums)
        total = sum(nums)
        ans = float('inf')
        for mask in range(1 << m):
            if mask.bit_count() != m // 2:
                continue
            s = sum(nums[i] for i in range(m) if mask >> i & 1)
            ans = min(ans, abs(total - 2 * s))
        return ans

