class Solution:
    def minimumDifference(self, nums: List[int]) -> int:
        from bisect import bisect_left
        n = len(nums) // 2
        total = sum(nums)
        lsum = [[] for _ in range(n + 1)]
        rsum = [[] for _ in range(n + 1)]
        for mask in range(1 << n):
            a = b = ca = cb = 0
            for i in range(n):
                if mask >> i & 1:
                    a += nums[i]
                    ca += 1
                    b += nums[n + i]
                    cb += 1
            lsum[ca].append(a)
            rsum[cb].append(b)
        for lst in rsum:
            lst.sort()
        ans = float('inf')
        for c in range(n + 1):
            right = rsum[n - c]
            for a in lsum[c]:
                j = bisect_left(right, total // 2 - a)
                for jj in (j - 1, j):
                    if 0 <= jj < len(right):
                        ans = min(ans, abs(total - 2 * (a + right[jj])))
        return ans

