class Solution {
public:
    int minimumDifference(vector<int>& nums) {
        int n = nums.size() / 2;
        long long total = accumulate(nums.begin(), nums.end(), 0LL);
        vector<vector<long long>> lsum(n + 1), rsum(n + 1);
        for (int mask = 0; mask < (1 << n); mask++) {
            long long a = 0, b = 0;
            int ca = 0, cb = 0;
            for (int i = 0; i < n; i++) {
                if (mask >> i & 1) {
                    a += nums[i];
                    ca++;
                    b += nums[n + i];
                    cb++;
                }
            }
            lsum[ca].push_back(a);
            rsum[cb].push_back(b);
        }
        for (auto& lst : rsum) sort(lst.begin(), lst.end());
        long long ans = LLONG_MAX;
        for (int c = 0; c <= n; c++) {
            auto& right = rsum[n - c];
            for (long long a : lsum[c]) {
                long long target = total / 2 - a;
                int j = lower_bound(right.begin(), right.end(), target) - right.begin();
                for (int jj : {j - 1, j}) {
                    if (jj >= 0 && jj < (int)right.size())
                        ans = min(ans, llabs(total - 2 * (a + right[jj])));
                }
            }
        }
        return (int) ans;
    }
};

