class Solution {
    public int minimumDifference(int[] nums) {
        int n = nums.length / 2;
        long total = 0;
        for (int x : nums) total += x;
        List<List<Long>> lsum = new ArrayList<>(), rsum = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            lsum.add(new ArrayList<>());
            rsum.add(new ArrayList<>());
        }
        for (int mask = 0; mask < (1 << n); mask++) {
            long a = 0, b = 0;
            int ca = 0, cb = 0;
            for (int i = 0; i < n; i++) {
                if ((mask >> i & 1) == 1) {
                    a += nums[i];
                    ca++;
                    b += nums[n + i];
                    cb++;
                }
            }
            lsum.get(ca).add(a);
            rsum.get(cb).add(b);
        }
        for (List<Long> lst : rsum) Collections.sort(lst);
        long ans = Long.MAX_VALUE;
        for (int c = 0; c <= n; c++) {
            List<Long> right = rsum.get(n - c);
            for (long a : lsum.get(c)) {
                long target = total / 2 - a;
                int j = lowerBound(right, target);
                for (int jj : new int[]{j - 1, j}) {
                    if (jj >= 0 && jj < right.size())
                        ans = Math.min(ans, Math.abs(total - 2 * (a + right.get(jj))));
                }
            }
        }
        return (int) ans;
    }

    private int lowerBound(List<Long> lst, long target) {
        int lo = 0, hi = lst.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (lst.get(mid) < target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

