    let total = 0;
    for (const x of nums) total += x;
    const lsum = Array.from({length: n + 1}, () => []);
    const rsum = Array.from({length: n + 1}, () => []);
    for (let mask = 0; mask < (1 << n); mask++) {
        let a = 0, b = 0, ca = 0, cb = 0;
        for (let i = 0; i < n; i++) {
            if ((mask >> i) & 1) {
                a += nums[i];
                ca++;
                b += nums[n + i];
                cb++;
            }
        }
        lsum[ca].push(a);
        rsum[cb].push(b);
    }
    for (const lst of rsum) lst.sort((p, q) => p - q);
    let ans = Infinity;
    for (let c = 0; c <= n; c++) {
        const right = rsum[n - c];
        for (const a of lsum[c]) {
            const target = Math.floor(total / 2) - a;
            let lo = 0, hi = right.length;
            while (lo < hi) {
                const mid = (lo + hi) >> 1;
                if (right[mid] < target) lo = mid + 1;
                else hi = mid;
            }
            for (const jj of [lo - 1, lo]) {
                if (jj >= 0 && jj < right.length)
                    ans = Math.min(ans, Math.abs(total - 2 * (a + right[jj])));
            }
        }
    }
    return ans;
};
